Dưới đây là cài đặt thuật toán sắp xếp nhanh (QuickSort) bằng C++ sử dụng phương pháp phân hoạch Lomuto:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

// Hàm phân hoạch (Partition) theo phương pháp Lomuto
// Chọn phần tử cuối cùng làm chốt (pivot)
int partition(std::vector<int>& arr, int low, int high) {
    int pivot = arr[high]; // Chọn pivot
    int i = low - 1;       // Chỉ số của phần tử nhỏ hơn pivot

    for (int j = low; j < high; ++j) {
        // Nếu phần tử hiện tại nhỏ hơn hoặc bằng pivot
        if (arr[j] <= pivot) {
            ++i;
            std::swap(arr[i], arr[j]);
        }
    }
    // Đưa pivot về đúng vị trí giữa hai mảng con
    std::swap(arr[i + 1], arr[high]);
    return i + 1;
}

// Hàm đệ quy QuickSort
void quickSort(std::vector<int>& arr, int low, int high) {
    if (low < high) {
        // pi là chỉ số nơi pivot đã được đặt đúng vị trí
        int pi = partition(arr, low, high);

        // Đệ quy sắp xếp mảng con bên trái và bên phải của pivot
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// Ví dụ chạy thử
int main() {
    std::vector<int> arr = {10, 7, 8, 9, 1, 5};
    int n = arr.size();

    std::cout << "Mảng ban đầu: ";
    for (int x : arr) std::cout << x << " ";
    std::cout << "\n";

    quickSort(arr, 0, n - 1);

    std::cout << "Mảng sau khi sắp xếp: ";
    for (int x : arr) std::cout << x << " ";
    std::cout << "\n";

    return 0;
}
```

### Đánh giá độ phức tạp thuật toán:
- **Thời gian trung bình & tốt nhất:** $O(n \log n)$
- **Thời gian xấu nhất:** $O(n^2)$ (xảy ra khi mảng đã sắp xếp sẵn và luôn chọn phần tử cuối làm pivot)
- **Không gian bộ nhớ:** $O(\log n)$ (ngăn xếp đệ quy)
